solution.solution.rs:
use std::collections::{BTreeMap, HashMap};
use std::num::ParseIntError;

struct Sale {
    product: String,
    region: String,
    cents: u64,
    qty: u32,
}

fn revenue_by_region(sales: &[Sale]) -> BTreeMap<String, u64> {
    sales.iter().fold(BTreeMap::new(), |mut map, s| {
        *map.entry(s.region.clone()).or_insert(0) += s.cents * s.qty as u64;
        map
    })
}

fn top_products(sales: &[Sale], n: usize) -> Vec<String> {
    let totals = sales.iter().fold(HashMap::new(), |mut map: HashMap<&str, u32>, s| {
        *map.entry(s.product.as_str()).or_insert(0) += s.qty;
        map
    });
    let mut ranked: Vec<(&str, u32)> = totals.into_iter().collect();
    ranked.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(b.0)));
    ranked.into_iter().take(n).map(|(p, _)| p.to_string()).collect()
}

fn average_unit_price(sales: &[Sale]) -> Option<f64> {
    if sales.is_empty() {
        return None;
    }
    Some(sales.iter().map(|s| s.cents as f64).sum::<f64>() / sales.len() as f64)
}

fn parse_all(texts: &[&str]) -> Result<Vec<i32>, ParseIntError> {
    texts.iter().map(|t| t.trim().parse::<i32>()).collect()
}

fn running_max(values: &[i32]) -> Vec<i32> {
    let mut best = i32::MIN;
    values.iter()
        .map(|&v| {
            best = best.max(v);
            best
        })
        .collect()
}

unitTests:
let sale = |p: &str, r: &str, cents: u64, qty: u32| Sale { product: p.into(), region: r.into(), cents, qty };
let sales = vec![
    sale("tea", "north", 250, 10),
    sale("cake", "north", 400, 3),
    sale("tea", "south", 250, 4),
    sale("mug", "south", 800, 5),
    sale("cake", "east", 400, 11),
    sale("mug", "north", 800, 1),
];

test("revenue per region", || {
    let r = revenue_by_region(&sales);
    check_eq(r.into_iter().collect::<Vec<_>>(), vec![("east".to_string(), 4400), ("north".to_string(), 4500), ("south".to_string(), 5000)]);
    check_eq(revenue_by_region(&[]).len(), 0);
});

test("top products", || {
    check_eq(top_products(&sales, 2), vec!["cake", "tea"]);
    check_eq(top_products(&sales, 9), vec!["cake", "tea", "mug"]);
});

test("average price", || {
    check_near(average_unit_price(&sales).unwrap(), 2900.0 / 6.0, 1e-9);
    check_eq(average_unit_price(&[]), None);
});

test("parsing everything or nothing", || {
    check_eq(parse_all(&[" 1", "2 ", "-3"]), Ok(vec![1, 2, -3]));
    check(parse_all(&["1", "x", "3"]).is_err());
    check_eq(parse_all(&[]), Ok(vec![]));
});

test("running max", || {
    check_eq(running_max(&[3, 1, 4, 1, 5]), vec![3, 3, 4, 4, 5]);
    check_eq(running_max(&[-5, -9]), vec![-5, -5]);
    check_eq(running_max(&[]), Vec::<i32>::new());
});

